<script lang="ts">
  import {untrack,onDestroy} from 'svelte';
  import {GitCommitHorizontal,Search,Undo2,FileCode,LoaderCircle} from 'lucide-svelte';
  import {api,type Commit,type CommitDetails} from './api';
  import DiffView from './DiffView.svelte';
  let {repoId,head,blocked,onrevert}:{repoId:number;head:string|null;blocked:boolean;onrevert:(hash:string,merge:boolean)=>void}=$props();
  let commits=$state<Commit[]>([]);let skip=$state(0);let query=$state('');let selected=$state<Commit|null>(null);let detail=$state<CommitDetails|null>(null);let file=$state<string|null>(null);let fileQuery=$state('');let code=$state('');let busy=$state(false);let diffBusy=$state(false);let error=$state('');
  let pageSequence=0,selectionSequence=0,diffSequence=0,alive=true;
  const filtered=$derived(commits.filter(c=>[c.subject,c.author,c.hash].some(text=>text.toLocaleLowerCase().includes(query.toLocaleLowerCase()))));
  const files=$derived((detail?.files??[]).filter(f=>f.path.toLocaleLowerCase().includes(fileQuery.toLocaleLowerCase())));
  $effect(()=>{repoId;head;untrack(()=>void loadPage(0));});
  onDestroy(()=>{alive=false;++pageSequence;++selectionSequence;++diffSequence;});
  async function loadPage(offset:number){const sequence=++pageSequence;const id=repoId;busy=true;error='';selected=null;detail=null;code='';++selectionSequence;++diffSequence;try{const rows=await api.history(id,offset);if(alive&&sequence===pageSequence){commits=rows;skip=offset;if(rows[0])void choose(rows[0]);}}catch(e){if(alive&&sequence===pageSequence)error=String(e);}finally{if(alive&&sequence===pageSequence)busy=false;}}
  async function choose(commit:Commit){const sequence=++selectionSequence;const id=repoId;selected=commit;detail=null;code='';fileQuery='';error='';diffBusy=false;++diffSequence;try{const result=await api.commitDetails(id,commit.hash);if(alive&&sequence===selectionSequence){detail=result;void showFile(result.files[0]?.path??null,commit.hash);}}catch(e){if(alive&&sequence===selectionSequence)error=String(e);}}
  async function showFile(path:string|null,hash=selected?.hash){if(!hash)return;const sequence=++diffSequence;const id=repoId;file=path;diffBusy=true;code='';try{const result=await api.commitDiff(id,hash,path);if(alive&&sequence===diffSequence)code=result;}catch(e){if(alive&&sequence===diffSequence)error=String(e);}finally{if(alive&&sequence===diffSequence)diffBusy=false;}}
</script>
<div class="history-workbench">
  <section class="panel commit-browser" aria-label="Commit history"><div class="panel-title">Commits <span>{skip+1}–{skip+commits.length}</span></div><div class="search-input history-search"><Search size={15}/><input aria-label="Find commits" placeholder="Find in this page" bind:value={query}/></div><div class="commit-list">{#each filtered as commit (commit.hash)}<button class="commit-choice" class:is-selected={selected?.hash===commit.hash} onclick={()=>{if(selected?.hash!==commit.hash)void choose(commit);}}><GitCommitHorizontal size={18}/><span><strong>{commit.subject}</strong><small>{commit.author} · {new Date(commit.timestamp*1000).toLocaleDateString()}</small><code>{commit.hash.slice(0,8)}</code></span></button>{:else}<p class="empty-small">{busy?'Loading commits…':query?'No matching commits':'No commits yet'}</p>{/each}</div><div class="history-paging"><button class="secondary" disabled={busy||skip===0} onclick={()=>loadPage(Math.max(0,skip-50))}>Previous</button><span>{skip/50+1}</span><button class="secondary" disabled={busy||commits.length<50} onclick={()=>loadPage(skip+50)}>Next</button></div></section>
  <section class="commit-inspector" aria-label="Selected commit">{#if error}<p class="connection-error" role="alert">{error}</p>{/if}{#if selected&&detail}<div class="panel commit-summary"><div><h2>{selected.subject}</h2><p>{selected.author} · {new Date(selected.timestamp*1000).toLocaleString()}</p><code>{selected.hash}</code></div><button class="secondary" disabled={blocked} title={blocked?'Commit changes and finish any active operation first':'Create a new commit that undoes this commit'} onclick={()=>onrevert(selected!.hash,detail!.parents.length>1)}><Undo2 size={15}/> Revert commit</button>{#if detail.body.trim()!==selected.subject}<pre>{detail.body.slice(0,20000)}</pre>{/if}{#if detail.parents.length>1}<small>Compared with the first parent. Reverting uses that same parent.</small>{/if}</div><div class="history-files-and-diff"><section class="panel history-files"><div class="panel-title">Files <span>{detail.files.length}{detail.truncated?'+':''}</span></div>{#if detail.files.length>8}<input aria-label="Filter commit files" placeholder="Filter files" bind:value={fileQuery}/>{/if}<div class="file-list">{#each files.slice(0,200) as item (item.path)}<button class="changed-file" class:file-selected={file===item.path} onclick={()=>{if(file!==item.path)void showFile(item.path);}}><FileCode size={15}/><span>{item.path}</span><b class:change-added={item.status==='A'} class:change-deleted={item.status==='D'}>{item.status}</b></button>{/each}</div>{#if detail.truncated||files.length>200}<small class="diff-limit">Preview limited. Filter files or use system Git for the full list.</small>{/if}</section><section class="panel diff-panel"><div class="panel-title"><span class="diff-filename">{file??'All files'}</span><button class="text-action" onclick={()=>showFile(null)}>All files</button></div>{#if diffBusy}<div class="diff-empty"><LoaderCircle size={20} class="spin"/> Loading commit diff…</div>{:else if code}<DiffView {code} label="Commit diff"/>{:else}<div class="diff-empty">No textual changes</div>{/if}</section></div>{:else if selected}<div class="empty-block" role="status">Loading commit…</div>{/if}</section>
</div>
